interface.signature:
interface FreeAgentConversationMessage {
  sessionId: string;
  messageIndex: string;  // zero-padded 6-digit, e.g. "000001"
  role: 'user' | 'assistant' | 'system';
  content: string;
  tokensIn?: number;
  tokensOut?: number;
  costUsd?: number;
  createdAt: string;  // ISO-8601
  toolCalls?: Array<{ id: string; name: string; input?: unknown }>;
  expiresAt: number;  // epoch seconds (DynamoDB TTL)
}

appendMessage(input: {
  sessionId: string;
  role: 'user' | 'assistant' | 'system';
  content: string;
  tokensIn?: number;
  tokensOut?: number;
  costUsd?: number;
  toolCalls?: unknown[];
}): Promise<FreeAgentConversationMessage>

getMessages(sessionId: string): Promise<FreeAgentConversationMessage[]>

listSessionsByOperator(operatorId: string, limit?: number): Promise<FreeAgentSession[]>
  // delegates to freeAgentSessionsRepo.listSessionsByOperator

listSessionsByScope(scope: { kind: string; id?: string }, limit?: number): Promise<FreeAgentSession[]>
  // delegates to freeAgentSessionsRepo.listSessionsByScope
